pageHelp.evidence={source:'Подтверждённые отчёты ТрансТрейда и интервалы ответственности водитель–машина.',meaning:'Дополнение пробега не создаёт новый рейс. Интервал ответственности отличается от длительности заявки и моточасов.',steps:['Загрузите источник с идентификатором заявки и временем актуальности.','Проверьте соответствие до подтверждения.','Для смен укажите доказанные границы и источник.'],note:'Без подтверждённых данных показатель остаётся неизвестным. Ручной импорт не является автономным получением из ТТ.',links:['orders','reconcile','quality']};
for(const [id,page] of Object.entries(sourcePages))pageHelp[id]={
 source:sourcePurpose[id],
 meaning:'Эта страница показывает состояние подключения и сведения последней проверки. Сохранённые записи, период и загрузка находятся на странице данных источника.',
 steps:['Прочитайте статус и подробности подключения.','Откройте данные источника, выберите даты и проверьте время последнего успеха.'],
 note:'Ошибка связи не означает, что сохранённые данные исчезли. Успешное подключение не подтверждает полноту всех записей и показателей.',links:[page,'connections']
};
function pageHelpMarkup(key){const h=pageHelp[key];if(!h)return '';return `<div class="page-help-grid"><section><h3>Откуда данные</h3><p>${esc(h.source)}</p></section><section><h3>Что означают показатели</h3><p>${esc(h.meaning)}</p></section><section><h3>Что делать</h3><ol>${h.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></section></div><div class="page-help-footer"><p>${esc(h.note)}</p><nav aria-label="Связанные разделы">${h.links.map(key=>routeLink(key)).join(' · ')}${key==='guide'?'':` · ${routeLink('guide','Полное руководство')}`}</nav></div>`}
const pageHelpOpen=new Map();
shell=function(){
 const previous=$('#page-help');if(previous)pageHelpOpen.set(previous.dataset.page,previous.dataset.motionExpanded===undefined?previous.open:previous.dataset.motionExpanded==='true');
 baseShell();const header=$('#main>header');header.querySelector('div').classList.add('page-title');
 if(sourcePages[tab])$('.header-context').textContent='Рабочее пространство / Настройки';
 const description=header.querySelector('.muted');description.textContent=pageDescriptions[tab]||sourcePurpose[tab]||'Состояние источника и доступ к сохранённым данным.';description.classList.add('page-description');
 const actions=document.createElement('div');actions.className='page-actions';actions.innerHTML='<button type="button" id="page-help-toggle" class="page-help-toggle" aria-controls="page-help" aria-expanded="false"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><path d="M9.7 9a2.4 2.4 0 0 1 4.6.9c0 1.7-2.3 1.9-2.3 3.6"/><path d="M12 16.5v.2" stroke-linecap="round"/></svg>Как пользоваться</button>';header.querySelector('.badge').replaceWith(actions);
 const help=document.createElement('details');help.id='page-help';help.className='page-help';help.dataset.page=tab;help.innerHTML=`<summary>Как устроен раздел «${esc(tabs[tab])}»</summary>${pageHelpMarkup(tab)}`;help.open=pageHelpOpen.get(tab)||false;header.after(help);
 const button=$('#page-help-toggle');button.setAttribute('aria-expanded',String(help.open));
 const rememberOpen=open=>{button.setAttribute('aria-expanded',String(open));pageHelpOpen.set(help.dataset.page,open)};
 help.addEventListener('disclosurechange',event=>rememberOpen(event.detail.open));
 help.addEventListener('toggle',()=>rememberOpen(help.dataset.motionExpanded===undefined?help.open:help.dataset.motionExpanded==='true'));
 button.onclick=event=>{if(window.fleetMotion)window.fleetMotion.toggle(help,undefined,{animate:event.detail!==0});else help.open=!help.open};
};

const baseTable=table;
table=function(headers,rows,click=false,searchable=true){const readable=rows.map(row=>row.map(cell=>typeof cell==='string'&&/^\d{4}-\d{2}-\d{2}(T[\d:.,+Z-]+)?$/.test(cell)?esc(businessDate(cell)):cell));const html=baseTable(headers.map(h=>h||'Действия'),readable,click,searchable);return rows.length?html:html.replace('Нет данных за выбранный период','Нет записей. Проверьте выбранный период и фильтры.')};

async function connections(){const target=$('#content'),rows=await api('connections');if(target!==$('#content'))return;
 target.innerHTML=`<div class="panel"><div class="panel-head"><h2>Источники данных</h2>${U.role==='admin'?'<button id="checkConnections">Проверить доступность серверов</button>':''}</div><p class="muted">Здесь показано состояние подключения. Таблицы и обновление выбранного периода находятся в разделе «Данные». Проверка доступности не загружает записи.</p><div class="source-grid">${rows.map(r=>`<article class="source-card"><h3>${esc(r.name)}</h3><span class="badge">${esc(r.status)}</span><p>${esc(sourcePurpose[r.id]||'Внешний источник')}</p><p class="muted">${r.authorization_checked_at?'Проверено: '+esc(localTime(r.authorization_checked_at)):r.checked_at?'Проверка сети: '+esc(localTime(r.checked_at)):'Проверка ещё не выполнялась'}</p><div class="actions">${routeLink(sourcePages[r.id],'Открыть данные')} ${routeLink(r.id,'Состояние подключения')}</div></article>`).join('')}</div></div><div class="panel"><h2>Данные из Excel</h2><p>Книги служат исходным снимком. Их не нужно загружать для ежедневной работы с API.</p>${routeLink('excel','Открыть импорт Excel')}</div><div class="panel"><h2>Проверка расчётов</h2><p>Пропуски показателей и спорные записи разобраны отдельно, с объяснением влияния на отчёты.</p>${routeLink('quality','Открыть качество данных')}</div>`;
 if($('#checkConnections'))$('#checkConnections').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await api('connections/check',{method:'POST',body:'{}'});if(target===$('#content'))await connections();toast('Проверка доступности завершена')}catch(x){toast(x.message);b.disabled=false}};
}
async function integration(id){const target=$('#content'),rows=await api('connections');if(target!==$('#content'))return;const source=rows.find(r=>r.id===id);if(!source)throw Error('Источник не найден');target.innerHTML=`<p>${routeLink('connections','← Все подключения')}</p><div class="panel"><div class="connection" data-source="${esc(id)}"><div><h2>${esc(source.name)}</h2><p>${esc(sourcePurpose[id])}</p></div><span class="badge">${esc(source.status)}</span></div><div class="panel-head"><h3>Работа с данными</h3>${routeLink(sourcePages[id],'Открыть '+tabs[sourcePages[id]].toLowerCase())}</div><p>Просмотр записей, выбор периода и загрузка из источника находятся на странице данных. Автоматическое обновление выполняется каждые 5 минут, пока работает сервер приложения.</p><details><summary>Подробности подключения</summary><p>${esc(source.detail)}</p><p class="muted">${source.checked_at?'Последняя проверка сети: '+esc(localTime(source.checked_at)):''}</p>${source.url?`<a href="${esc(source.url)}" target="_blank" rel="noreferrer">Документация / кабинет ↗</a>`:''}</details></div>`}
async function sourceData(id){const target=$('#content');if(U.role!=='admin'){target.innerHTML=`<div class="panel"><h2>Доступ руководителя</h2><p>Исходные операции и загрузка источников доступны руководителю. Сводные показатели доступны в аналитике.</p>${routeLink('statistics','Открыть статистику')}</div>`;return}
 target.innerHTML=`<p>${routeLink(id,'Состояние подключения')} · ${routeLink(id==='monitoring'?'reconcile':'fuelcards',id==='monitoring'?'Сверить с заявками':'Связать карты с автомобилями')}</p>${id==='monitoring'?'<div class="panel" id="monitoring-panel"></div><div class="panel" id="monitoring-history-panel"></div>':`<div class="panel" id="${id}-panel"></div>`}`;
 if(id==='neftm')await loadNeftmPanel();if(id==='rosneft')await loadRosneftPanel();if(id==='monitoring'){await loadMonitoringPanel();if(target!==$('#content'))return;await loadMonitoringHistoryPanel()}}

function excelImport(){const labels={trips:'Заявки',satellite:'Спутниковые интервалы',statuses:'Статусы',plans:'Назначения',routes:'Маршруты'};$('#content').innerHTML=`<div class="panel"><div class="panel-head"><h2>Исходный снимок</h2>${U.role==='admin'?'<button id="reimport">Повторить импорт исходных книг</button>':''}</div><p>Последний импорт: ${esc(localTime(D.meta.imported_at))}</p>${table(['Книга','Контрольная сумма'],D.meta.files.map(f=>[esc(f.name),`<code>${esc(f.sha256)}</code>`]))}<p>${Object.entries(D.meta.counts).map(([k,v])=>`${labels[k]||esc(k)}: ${fmt(v)}`).join(' · ')}</p><p class="muted">Это объём исходного снимка. Текущая рабочая база также содержит заявки API и ручные записи.</p></div>${U.role==='admin'?'<div class="panel"><h2>Загрузить новые книги</h2><form id="upload" class="grid"><label>Книга статистики<input type="file" name="statistics" accept=".xlsx" required></label><label>Книга планировщика<input type="file" name="planner" accept=".xlsx" required></label><div class="actions wide"><button class="primary">Импортировать книги</button></div></form><p class="muted">Импорт добавляет периоды. Ручные записи и сохранённые назначения остаются, повторные строки не добавляются. Исходные файлы не изменяются.</p></div>':''}<div class="panel"><h2>Как используются таблицы</h2><p>Заявки, спутник, планы и справочники имеют отдельные страницы. Замечания к исходным книгам показаны отдельно от текущих проблем.</p>${routeLink('guide','Карта Excel → приложение')} · ${routeLink('quality','Качество данных')}</div>`;
 const importNow=async(b,body)=>{b.disabled=true;try{await api('import',{method:'POST',body});await refresh();toast('Книги импортированы')}catch(x){toast(x.message);b.disabled=false}};
 if($('#reimport'))$('#reimport').onclick=e=>importNow(e.currentTarget,'{}');if($('#upload'))$('#upload').onsubmit=e=>{e.preventDefault();importNow(e.target.querySelector('button'),new FormData(e.target))}}

let qualityFilter='',qualityOffset=0;
function qualityKind(row){const s=row.issue;if(s.includes('API: есть отсутствующие'))return row.record&&(row.record.revenue==null||row.record.payout==null)?'source':'missing';if(s.includes('Повтор назначения'))return 'duplicate';if(s.includes('Не назначен'))return 'assignment';if(s.includes('Назначение требует проверки'))return 'review';if(s.includes('Проверьте категорию'))return 'category';if(s.includes('Служебное обозначение'))return 'directory';return 'source'}
const qualityInfo={review:['Спорное назначение','Назначение исключено из итогов до проверки.','Сверьте ресурс, водителя, маршрут и состояние с исходным назначением.','planner'],duplicate:['Повторы назначений','Спорные повторы исключены из итогов плана.','Укажите разные номера смен для действительных рейсов или отмените лишнее назначение.','planner'],assignment:['Работа без назначения','Рейс включён в план, но водитель или машина не выбраны.','Откройте назначение и выберите водителя и автомобиль.','planner'],category:['Проверить категорию заявки','Отрицательная сумма или отсутствующий автомобиль могут искажать загрузку.','Сверьте заявку в источнике. Доплату или удержание отметьте соответствующей категорией.','orders'],source:['Расхождения с ТрансТрейдом','Запись сохранена, но API вернул неполные или отличающиеся сведения.','Сверьте номер и содержание заявки. Локальная версия не удаляется автоматически.','orders'],directory:['Служебные записи справочника','Это обозначения из Excel, а не отдельные машины или водители.','Используйте реальный объект для новых назначений. Старую запись можно архивировать.','directories'],missing:['API не передаёт часть показателей','Неизвестные значения показаны «—» и не заменяются нулём.','Километраж ТТ API не предоставляет. Пробег автомобиля смотрите в показаниях спутника.','monitoringdata']};
async function qualityPage(){const target=$('#content'),result=await api('workspace/report?'+new URLSearchParams({from,to,vehicle:car,driver,mode:'quality'}));if(target!==$('#content'))return;
 const grouped={};result.rows.forEach(r=>(grouped[qualityKind(r)]??=[]).push(r));const all=result.rows.filter(r=>qualityKind(r)!=='missing');const rows=qualityFilter?(grouped[qualityFilter]||[]):all;qualityOffset=Math.min(qualityOffset,Math.max(0,Math.floor((rows.length-1)/100)*100));const visible=rows.slice(qualityOffset,qualityOffset+100);
 target.innerHTML=`<div class="note"><b>Как читать эту страницу</b><p>«Требует проверки» — действие с конкретной записью. «Ограничение источника» — показатель, который источник не передаёт. Замечания исходного Excel находятся внизу и могут уже не относиться к обновлённым заявкам.</p></div>${metrics([['Требуют проверки',fmt(all.length),'Замечаний за выбранный период и к справочникам'],['Ограничения API',fmt((grouped.missing||[]).length),'Записей с неизвестными показателями'],['Замечания импорта',fmt(D.meta.issues.length),'Исторический снимок Excel, все периоды']])}<div class="quality-grid">${Object.entries(qualityInfo).filter(([key])=>grouped[key]?.length).map(([key,[name,impact,action,dest]])=>`<article class="quality-card"><span class="badge">${key==='missing'?'Ограничение источника':'Требует проверки'} · ${fmt(grouped[key].length)}</span><h3>${name}</h3><p>${impact}</p><p class="muted">${action}</p><div class="actions"><button data-quality="${key}">Показать записи</button>${routeLink(dest,'Открыть раздел')}</div></article>`).join('')}</div><div class="panel"><div class="panel-head"><h2>${qualityFilter?qualityInfo[qualityFilter][0]:'Записи для проверки'}</h2><button id="quality-reset">Все требующие проверки</button></div>${rows.length?`<p class="muted">Показаны ${qualityOffset+1}–${Math.min(qualityOffset+100,rows.length)} из ${rows.length}. ${qualityFilter?'':'Ограничения API исключены из этого списка.'}</p>${table(['Дата','Объект / заявка','Что проверить','Действие'],visible.map((r,i)=>[esc(r.date||'Справочник'),esc(r.object),esc(r.issue),`<button data-quality-record="${i}">${r.record?'Открыть запись':'Открыть справочник'}</button>`]))}`:'<div class="empty"><h3>Записей для проверки нет</h3><p>В выбранном периоде не найдено замечаний этого типа. Это не подтверждение полноты данных.</p></div>'}${rows.length>100?`<div class="actions"><button id="quality-prev" ${qualityOffset?'':'disabled'}>Предыдущие</button><button id="quality-next" ${qualityOffset+100<rows.length?'':'disabled'}>Следующие</button></div>`:''}</div><div class="panel"><h2>Замечания исходного Excel</h2><p>Это результат проверки книги при импорте ${esc(localTime(D.meta.imported_at))}. Обновлённые через API заявки проверяются выше.</p><details><summary>Открыть замечания импорта (${fmt(D.meta.issues.length)})</summary>${importIssueGroups()}</details><p class="muted">Отчёты приложения рассчитываются из исходных записей. Ошибки ссылок в формулах Excel не переносятся в расчёты приложения; результаты сверки книг приведены в руководстве.</p>${routeLink('excel','Проверить исходные книги')}</div>`;
 document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{qualityFilter=b.dataset.quality;qualityOffset=0;qualityPage()});$('#quality-reset').onclick=()=>{qualityFilter='';qualityOffset=0;qualityPage()};if($('#quality-prev'))$('#quality-prev').onclick=()=>{qualityOffset-=100;qualityPage()};if($('#quality-next'))$('#quality-next').onclick=()=>{qualityOffset+=100;qualityPage()};
 document.querySelectorAll('[data-quality-record]').forEach(b=>b.onclick=()=>{const r=visible[+b.dataset.qualityRecord];if(r.kind==='plans'){if(U.role==='viewer')navigate('planner');else planForm(r.record)}else if(r.kind==='trips')showTrips([r.record],'Заявка № '+r.record.id);else{directoryKind=r.kind;navigate('directories')}})}
function importIssueGroups(){const groups={};D.meta.issues.forEach(text=>{const match=text.match(/^([^:]+):\s*(.*)$/),source=match?.[1]||'Импорт',detail=match?.[2]||text;const key=detail.startsWith('маршрут не найден')?'Маршрут не найден':detail.startsWith('неизвестный объект')?'Неизвестный спутниковый объект':detail;(groups[key]??=[]).push(source)});return Object.entries(groups).map(([issue,refs])=>`<details><summary>${esc(issue)} · ${refs.length}</summary><p>${refs.map(esc).join(', ')}</p></details>`).join('')||'<p>Замечаний при импорте не обнаружено.</p>'}

const extraDescriptions={coverage:['Подтверждённых периодов пока нет','Поэтому отсутствие записи в плане или факте считается неизвестным. После сверки всех машин добавьте проверенный период.','Подтвердить период'],card_bindings:['Карты пока не связаны с автомобилями','Покупки сохраняются, но не распределяются по машинам в экономике. Добавьте номер карты, автомобиль и даты использования.','Связать карту с автомобилем'],expenses:['Дополнительные расходы не внесены','Здесь можно учесть ремонт, платные дороги и другие подтверждённые расходы. Операции топливных карт повторно вводить не нужно.','Добавить расход']};
const baseExtraTable=extraTable;
extraTable=function(kind){baseExtraTable(kind);const [title,description,action]=extraDescriptions[kind],panel=$('#content .panel'),add=$('#extraAdd'),head=document.createElement('div');head.className='panel-head';head.innerHTML=`<h2>${extraLabels[kind]}</h2>`;if(add){add.textContent=action;head.append(add)}panel.prepend(head);if(!(D[kind]||[]).length){panel.querySelector('.table-wrap').outerHTML=`<div class="empty"><h3 class="empty-title">${title}</h3><p class="empty-description">${description}</p>${U.role!=='admin'?'<p>Добавить запись может руководитель.</p>':''}</div>`}};

const baseOrders=orders;
orders=function(){baseOrders();const head=$('#content .panel-head');head.insertAdjacentHTML('beforeend',routeLink('transtrade','Подключение ТрансТрейда'));if(U.role==='admin'){$('#content').insertAdjacentHTML('beforeend','<details class="panel"><summary>Обновление заявок и сверка истории</summary><div id="transtrade-panel"></div></details>');loadTranstradePanel().catch(e=>toast(e.message))}};

function guideConnections(){return `<div class="panel"><h2>Как данные связаны между собой</h2><p>У каждого источника своя задача. Одно событие не нужно заводить повторно в другой таблице ради отчёта.</p>${table(['Связь','По чему соединяется','Что получается'],[
 ['Справочники → Планировщик','Дата + маршрут + водитель + автомобиль / ресурс','Назначение с сохранённой ставкой, км и длительностью маршрута.'],
 ['Планировщик + Заявки → План–факт','Одинаковый период и группировка по машине, водителю или паре','Сравнение ожидаемой и зарегистрированной работы после проверки полноты.'],
 ['Заявки + Спутник → Сверка','Автомобиль + дата','Сравнение сведений о поездках с суточными показаниями машины.'],
 ['Календарь + Заявки → Работа и простои','Объект (машина или водитель) + дата','Рабочие дни, дни статусов и их пересечения.'],
 ['Операции карт + Карты и автомобили → Экономика','Поставщик + номер карты + дата операции внутри срока привязки','Покупки и возвраты, отнесённые к нужной машине.'],
 ['Заявки + привязанные покупки + Расходы → Экономика','Автомобиль + выбранный период','Остаток после известных затрат; не полная чистая прибыль.']
 ],false,false)}<p class="muted">Календарь дат даёт месяц, неделю и другие разрезы. Справочники хранят общие объекты; сводные заново считают исходные записи. Данные спутника не распределяются автоматически между водителями, а покупки по картам не превращаются в расход топлива.</p></div><div class="panel"><h2>Путеводитель по меню</h2><p>Откройте нужный раздел ниже: внутри объяснены источник, смысл показателей и первые действия.</p>${Object.entries(sections).filter(([key])=>key!=='help').map(([section,keys])=>`<h3>${esc(sectionNames[section])}</h3>${keys.filter(key=>key!=='users'||U.role==='admin').map(key=>`<details class="guide-section"><summary>${esc(tabs[key])} — ${esc(pageDescriptions[key])}</summary><p>${routeLink(key,'Открыть раздел «'+tabs[key]+'»')}</p>${pageHelpMarkup(key)}</details>`).join('')}`).join('')}</div>`}

function userGuide(){const map=[["Статистика / Рент", "economics", "Пояснения к налоговым коэффициентам. Суммы источника сохранены; неоднозначные коэффициенты 1,05 / 1,22 дополнительно не применяются"], ["Статистика / Анализ", "statistics", "Производная аналитика. 56 формул с #REF!; вместо сломанных ссылок расчёт из записей"], ["Статистика / Сравнительная", "reconcile", "Сводная сравнения по машинам. Показатели считаются по выбранному периоду и машине"], ["Статистика / Сруктура (скрытый)", "orders", "Схема полей источников. Служебная схема, а не дополнительные рейсы"], ["Статистика / Календарь", "statistics", "Даты и календарные разрезы. Даты, недели, месяцы, кварталы, годы рассчитываются из даты; лист не копируется как независимые факты"], ["Статистика / Спутник", "telemetry", "335 интервалов навигации. Все исходные интервалы присутствуют; API-показания видны отдельно"], ["Статистика / Справочник", "directories", "Машины, водители, причины, сопоставления объектов. Сущности и соответствия используются при импорте; разные написания не сливаются без решения владельца"], ["Статистика / СтатусВодитель", "calendar", "Сводный календарь водителей. Представление из заявок и отдельных статусов"], ["Статистика / СтатусАвтомобиль", "calendar", "Сводный календарь машин. Представление из заявок и отдельных статусов"], ["Статистика / ТрансТрейд", "orders", "Заявки и помещённые в тот же лист простои. 996 денежных записей; 134 строки без номера с причиной простоя становятся статусами, а не рейсами"], ["Статистика / Блокнот", "calendar", "Ручные причины отсутствия работы. Статусы машины и водителя хранятся отдельно; повторы объединяются с сохранением источника"], ["Статистика / Статистика", "statistics", "Итоговые сводные. Группировки и показатели из рабочих записей, без копирования старой сводной как новых данных"], ["Планировщик / Календарь", "planner", "Календарные разрезы плана. Даты рассчитываются приложением"], ["Планировщик / Водители", "directories", "Водители и компания. Отдельные сущности водителей; принадлежность используется для ставки партнёра"], ["Планировщик / Маршруты Почта", "directories", "114 маршрутов, ставки, км, часы. Ставки и показатели перенесены; при назначении ставка сохраняется для конкретного плана"], ["Планировщик / ПланМашин", "planner", "Сводный календарь плана по машинам. Представление из назначений; в ячейке маршрут, водитель, состояние и действия"], ["Планировщик / ПланМаршрут", "planner", "Сводный календарь по маршрутам. Те же назначения; в ячейке машина, водитель, состояние и действия"], ["Планировщик / Автомобили", "directories", "Машины, партнёрские ресурсы, служебные строки. Значения «Партнёр» / «Чартер ООО» сохранены как принадлежность; фамилии не превращаются в госномера"], ["Планировщик / Логист", "planner", "1436 плановых назначений. Все исходные назначения сохранены; повторные и неназначенные записи отмечаются для проверки"], ["Планировщик / Статистика", "planreport", "Сводки плановой выручки, выплат, км и часов. Сводка плана отдельно от факта; отклонения требуют подтверждённой полноты обоих источников"]];
 $('#content').innerHTML=`<div class="panel"><h2>С чего начать</h2><ol><li>Откройте «Данные → Заявки ТрансТрейд» и выберите нужный период.</li><li>Для будущей работы назначьте маршруты в «Планирование → Планировщик».</li><li>Посмотрите выручку, выплаты и загрузку в «Аналитика → Статистика».</li><li>Проверьте замечания в «Контроль → Качество данных».</li></ol></div><div class="guide-grid"><article class="guide-card"><h2>План и выполненная работа</h2><p>Планировщик → Сводка плана → План–факт.</p><p>Вы сравниваете, что собирались выполнить и что зарегистрировано в заявках. Для корректного сравнения выбирайте один период.</p>${routeLink('planner','Назначить работу')} · ${routeLink('comparison','Сравнить план и факт')}</article><article class="guide-card"><h2>Заявки и спутник</h2><p>Заявки ТрансТрейд + Показания спутника → Сверка со спутником.</p><p>Вы проверяете, согласуются ли заявленные рейсы с пробегом машины. Это отдельная проверка, она не использует предварительный план.</p>${routeLink('reconcile','Открыть сверку')}</article></div>${guideConnections()}<div class="panel guide-map"><h2>Где теперь привычная таблица Excel</h2><p>Все 20 листов двух книг. Введите название листа в поиске таблицы.</p>${table(['Таблица / лист Excel','Раздел приложения','За что отвечает'],map.map(([name,key,desc])=>[esc(name),routeLink(key),esc(desc)]))}</div><div class="panel"><h2>Как читать показатели</h2><ul><li><b>«—» — неизвестно.</b> Источник не передал показатель или период не подтверждён.</li><li><b>0 — известный ноль.</b> Это не замена отсутствующим данным.</li><li><b>Полнота периода</b> — ваше подтверждение всех машин и записей, а не процент загрузки. Только после проверки отсутствие записи может считаться нулём.</li><li><b>Моточасы</b> — время работы двигателя. Длительность интервала Excel, движение и холостой ход показаны отдельно.</li><li><b>Выручка минус выплаты</b> — разница по заявкам. Остаток в экономике учитывает известные расходы; это не полная чистая прибыль.</li><li><b>Покупка топлива и расход топлива</b> — разные показатели. Покупки поступают из карт, расход — из спутника. Для распределения покупок укажите карты и автомобили.</li></ul>${routeLink('coverage','Полнота периодов')} · ${routeLink('fuelcards','Карты и автомобили')}</div><div class="panel"><h2>Обновление данных</h2><p>Каждые 5 минут работающий сервер запрашивает подключённые источники за текущий месяц. Спутниковая история обновляется за завершённые сутки. Открытая страница получает новые данные; редактируемая форма сохраняется.</p><p>Кнопка «Обновить данные» запускает обновление выбранного периода (до 31 дня) для руководителя. Статус каждого источника и ошибки видны рядом. Закрытие страницы не останавливает сервер; выключение компьютера останавливает обновление.</p><p>Excel не перечитывается каждые 5 минут. Новые книги загружаются отдельно в «Импорт Excel».</p></div><div class="panel"><h2>Что ещё нужно заполнить</h2><p>Связать топливные карты с автомобилями, внести дополнительные расходы и проверить полноту сравниваемых периодов. API ТрансТрейда не передаёт километраж: для фактического пробега используйте спутник.</p>${routeLink('quality','Посмотреть конкретные замечания')}</div>`}

// Normalize table surfaces created by older report renderers without losing handlers.
function normalizePanels(){document.querySelectorAll('#content>.panel').forEach(panel=>{if(panel.dataset.normalized)return;panel.dataset.normalized='true';const toolbar=panel.querySelector(':scope>.toolbar');if(toolbar){toolbar.classList.add('panel-head');const heading=document.createElement('h2');heading.textContent=tabs[tab];toolbar.prepend(heading)}else{const direct=panel.querySelector(':scope>button#export');if(direct){const head=document.createElement('div');head.className='panel-head';head.innerHTML=`<h2>${esc(tabs[tab])}</h2>`;direct.before(head);head.append(direct)}}});document.querySelectorAll('#content>.note').forEach(note=>{if(note.textContent.length<700||note.dataset.compact)return;note.dataset.compact='true';const details=document.createElement('details');details.className='note';details.dataset.compact='true';const summary=document.createElement('summary');summary.textContent='Как рассчитаны показатели и что учитывать';note.replaceWith(details);details.append(summary,note);note.classList.remove('note')})}
new MutationObserver(normalizePanels).observe(document.getElementById('content')||document.getElementById('app'),{childList:true,subtree:true});

// Fuel tables read their selected period from retained history, not the latest sync snapshot.
const fuelPeriods={neftm:{from,to},rosneft:{from,to}};
const fuelNames={neftm:'Нефтьмагистраль',rosneft:'Роснефть'};
function businessDate(value){const text=String(value||'');if(!text)return '—';if(/^\d{4}-\d{2}-\d{2}$/.test(text))return text.split('-').reverse().join('.');if(/^\d{4}-\d{2}-\d{2}T/.test(text)){if(/(?:Z|[+-]\d{2}:\d{2})$/.test(text))return localTime(text);const [d,t]=text.split('T');return d.split('-').reverse().join('.')+' '+t.slice(0,8)}return text}
async function loadFuelPanel(provider){const panel=$('#'+provider+'-panel');if(!panel)return;const selection={...fuelPeriods[provider]};try{const [state,snap]=await Promise.all([api(provider),api('fuel-history/'+provider+'?'+new URLSearchParams(selection))]);if(!panel.isConnected)return;drawFuelPanel(panel,provider,state.configured,snap)}catch(e){if(panel.isConnected)panel.innerHTML=`<h2>${fuelNames[provider]}</h2><p role="alert">${esc(e.message)}</p>`}}
loadNeftmPanel=()=>loadFuelPanel('neftm');loadRosneftPanel=()=>loadFuelPanel('rosneft');
function drawFuelPanel(panel,provider,configured,snap){const rows=snap.rows||[],rn=provider==='rosneft',notes=Object.fromEntries((snap.cards||[]).map(c=>[c.Num,c.Rem]));
 const kind=v=>({1:'Пополнение счёта',4:'Списание со счёта',11:'Покупка',24:'Возврат'}[v]||'Тип '+v);
 const cols=rn?[['Date','Дата и время терминала'],['Card','Карта'],['note','Примечание карты сейчас'],['GName','Товар / услуга'],['GCat','Категория'],['Value','Количество'],['Price','Цена АЗС, ₽'],['Sum','Сумма до скидки, ₽'],['DSum','Скидка, ₽'],['NetSum','После скидки, ₽'],['Type','Операция'],['Address','АЗС / адрес'],['Code','ID операции']]:[['dateRec','Дата и время, МСК'],['cardNumber','Карта'],['cardHolder','Держатель'],['serviceName','Товар / услуга'],['amount','Количество'],['priceClient','Цена'],['costClient','Сумма'],['currencyName','Валюта / кошелёк'],['typeNumber','Операция'],['posNum','Номер ТО'],['terminalNum','Терминал']];
 const numeric=new Set(['Value','Price','Sum','DSum','NetSum','amount','priceClient','costClient']);
 const value=(r,k)=>k==='note'?(notes[r.Card]||'—'):k==='GCat'?({FUEL:'Топливо',GOODS:'Товары',SERVICE:'Услуги'}[r[k]]||r[k]):['Type','typeNumber'].includes(k)?kind(r[k]):['Date','dateRec'].includes(k)?businessDate(r[k]):numeric.has(k)?fmt(r[k]==null?null:Number(r[k])):r[k];
 panel.innerHTML=`<div class="panel-head"><h2>${fuelNames[provider]} · операции</h2><button id="fuel-export" ${rows.length?'':'disabled'}>Скачать CSV</button></div><form id="fuel-period" class="toolbar"><label>С<input type="date" name="from" value="${esc(snap.from)}" required></label><label>По<input type="date" name="to" value="${esc(snap.to)}" required></label><button type="submit" name="action" value="show">Показать период</button><button type="submit" name="action" value="sync" class="primary" ${configured?'':'disabled'}>Обновить из источника</button></form><p id="fuel-status" role="status">${rows.length?`В сохранённой базе ${fmt(rows.length)} операций за ${businessDate(snap.from)} — ${businessDate(snap.to)}.`:'За выбранный период операций в базе нет.'} ${snap.complete?'Период загружен полностью.':'Полнота загрузки не подтверждена.'} ${snap.synced_at?'Обновлено: '+esc(localTime(snap.synced_at))+'.':''}</p><p class="muted">«Показать период» читает сохранённые операции. «Обновить из источника» запрашивает API за эти даты, до 31 дня. Покупки участвуют в экономике после привязки карты к машине.</p>${rows.length?table(cols.map(c=>c[1]),rows.map(r=>cols.map(([k])=>esc(value(r,k))))):`<div class="empty"><h3>Нет операций в выбранном периоде</h3><p>Выберите загруженные даты или получите данные из источника. Отсутствие загрузки не означает отсутствие покупок.</p></div>`}<details><summary>Что учитывать в расчётах</summary><p>Возвраты учитываются отдельно от покупок. ${rn?'Количество услуг может быть не в литрах. Примечание карты относится к её текущему состоянию, время операции — местное время терминала. Данные могут задерживаться до двух часов.':'Количества и суммы показаны в единицах источника; проверяйте валюту или кошелёк операции.'} Имя держателя не определяет автомобиль автоматически.</p>${routeLink('fuelcards','Проверить привязки карт')}</details>`;
 panel.querySelector('#fuel-export').onclick=()=>csv(rows.map(r=>Object.fromEntries(cols.map(([k,label])=>[label,value(r,k)]))));
 panel.querySelector('#fuel-period').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(!b.from||!b.to||b.from>b.to||(Date.parse(b.to)-Date.parse(b.from))/86400000>=31)return toast('Выберите период от 1 до 31 дня');fuelPeriods[provider]=b;const sync=e.submitter?.value==='sync';e.target.querySelectorAll('button').forEach(x=>x.disabled=true);try{if(sync){panel.querySelector('#fuel-status').textContent='Получаем операции из источника…';await api(provider+'/sync',{method:'POST',body:JSON.stringify(b)})}if(panel.isConnected)await loadFuelPanel(provider);if(sync)toast('Операции обновлены')}catch(x){if(panel.isConnected){panel.querySelector('#fuel-status').textContent=x.message;e.target.querySelectorAll('button').forEach(x=>x.disabled=false)}}};
}
